package com.rohit.inventory.service;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.rohit.inventory.event.DomainEvent; import java.util.UUID; import org.springframework.context.ApplicationEventPublisher; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service;
@Service public class AuditService { private final JdbcTemplate jdbc; private final ObjectMapper json; private final ApplicationEventPublisher events; public AuditService(JdbcTemplate jdbc,ObjectMapper json,ApplicationEventPublisher events){this.jdbc=jdbc;this.json=json;this.events=events;} public void record(UUID actorId,String action,String entityType,UUID entityId,Object newState){ try { String payload=json.writeValueAsString(newState); jdbc.update("insert into audit_logs(actor_user_id,action,entity_type,entity_id,new_state) values (?,?,?,?,cast(? as jsonb))",actorId,action,entityType,entityId,payload); events.publishEvent(new DomainEvent(UUID.randomUUID(),action,java.time.Instant.now(),actorId,null,null,entityType,entityId,null,null,payload)); } catch(JsonProcessingException e){throw new IllegalStateException("Could not serialize audit event",e);} } }
